insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-250', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Among Li, Na and K, potassium is the most metallic because it has the', '["smallest size and highest IE","largest size and the lowest ionisation enthalpy","highest electronegativity","closed 3p⁶ valence shell"]'::jsonb, 1, 'Down group 1, size rises and IE falls, so K loses its 4s electron most readily of the three.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'metallic-character') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
