insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-265', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Fluorine shows only the −1 oxidation state in its compounds, whereas chlorine can show', '["only −1 as well","several positive oxidation states","the +8 state in ClF₈","no covalent compounds"]'::jsonb, 1, 'F is the most electronegative element and has no vacant d orbitals, so it never takes a positive OS.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'anomalous-first') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
