insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-266', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Lithium resembles magnesium more than sodium because Li⁺ and Mg²⁺ have similar charge-to-radius ratios, giving both a', '["low polarising power","high polarising power","closed 3d¹⁰ shell","gaseous metallic lattice"]'::jsonb, 1, 'The two ions polarise anions strongly, so their oxides, fluorides and organometallic compounds look alike — the diagonal relationship.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'anomalous-first') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
