insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-268', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Effective nuclear charge experienced by a valence electron is written $Z_{\mathrm{eff}}=Z-\sigma$, where $\sigma$ is the', '["atomic mass","screening constant","mass number","group number"]'::jsonb, 1, 'Inner electrons cancel part of Z; the remainder is the effective nuclear charge felt by the outer electron.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'periodic-trends-general') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
