insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-281', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Na⁺ and neon are isoelectronic, but Na⁺ has the higher ionisation enthalpy because of its', '["smaller nuclear charge","greater nuclear charge","extra 3s electron","f-block contraction"]'::jsonb, 1, 'Both have 10 electrons; Z(Na⁺) = 11 > Z(Ne) = 10, so the Na⁺ cloud is more tightly bound.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'periodic-trends-general') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
